import glob, yaml, re, os
mis = re.compile(r'と読める|とも読める|に読める|読み取れる|読み違|と取る|と取れ|と解釈|誤読|読み方ができ|と読まれ|読めてしまう|2 通りに|二通りに|曖昧|あいまい')
prior = re.compile(r'前の回|前回の修正|回目の修正|の修正 ?\(|修正が(足|書|変|残|持ち込|作)|修正で(足|書|変|残|持ち込)|P\d+ ?(が|で)(足|書|変|直)|[0-9a-f]{7,8}\)? ?(が|で)(足|書|変|直|追加)|直したとき|直した際|足したとき|書き換えたとき|修正のとき|修正の際|修正した際|修正したとき|自分で(足|書)|この(ブランチ|ループ)の.{0,12}修正|増分')
tot=adopt=m_all=m_late=m_late_prior=late=0
for p in sorted(glob.glob('tmp/review-triages/*.yaml')+glob.glob('docs/review-triage/*.yaml')):
    try: d=yaml.safe_load(open(p))
    except Exception: continue
    for ri,run in enumerate((d or {}).get('runs') or [],1):
        f2p={}
        for pl in run.get('plans') or []:
            for fid in pl.get('finding_ids') or []: f2p[fid]=pl
        for f in run.get('findings') or []:
            if f.get('verdict')!='adopted': continue
            adopt+=1
            s=str(f.get('summary') or '')
            hit=bool(mis.search(s))
            m_all+=hit
            if ri>=2:
                late+=1
                if hit:
                    m_late+=1
                    txt=s+str(f.get('verdict_reason') or '')+str((f2p.get(f.get('id')) or {}).get('cause') or '')
                    m_late_prior+=bool(prior.search(txt))
print('adopted',adopt,'misread',m_all,f'{m_all*100/adopt:.0f}%','| run>=2',late,'misread',m_late,'prior-fix',m_late_prior)
